import{_ as p,a0 as o,w as r,s as d,I as i,x as a,a1 as e,A as t,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"如何在 Linux 上安裝 Elasticsearch 和 Kibana | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上安裝 Elasticsearch 和 Kibana | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上安裝 Elasticsearch 和 Kibana | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上安裝 Elasticsearch 和 Kibana | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20190709 How to install Elasticsearch and Kibana on Linux","title":"如何在 Linux 上安裝 Elasticsearch 和 Kibana","tag":"201908","desc":""},"relativePath":"201908/20190709 How to install Elasticsearch and Kibana on Linux.md","filePath":"[post].md"}'),u={name:"201908/20190709 How to install Elasticsearch and Kibana on Linux.md"};function c(h,s,g,b,k,f){const n=o("Link");return r(),d("div",null,[s[38]||(s[38]=i("h1",{id:"如何在-linux-上安裝-elasticsearch-和-kibana",tabindex:"-1"},[a("如何在 Linux 上安裝 Elasticsearch 和 Kibana "),i("a",{class:"header-anchor",href:"#如何在-linux-上安裝-elasticsearch-和-kibana","aria-label":"Permalink to “如何在 Linux 上安裝 Elasticsearch 和 Kibana”"},"​")],-1)),s[39]||(s[39]=i("blockquote",null,[i("p",null,"獲取我們關於安裝兩者的簡化説明。")],-1)),s[40]||(s[40]=i("p",null,[i("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/rh_003499_01_linux31x_cc.png?itok=Pvim4U-B",alt:"5 pengiuns floating on iceburg",title:"5 pengiuns floating on iceburg"})],-1)),i("p",null,[s[1]||(s[1]=a("如果你渴望學習基於開源 Lucene 庫的著名開源搜索引擎 Elasticsearch，那麼沒有比在本地安裝它更好的方法了。這個過程在 ",-1)),e(n,{href:"https://www.elastic.co/guide/en/elasticsearch/reference/current/rpm.html"},{default:t(()=>[...s[0]||(s[0]=[a("Elasticsearch 網站",-1)])]),_:1}),s[2]||(s[2]=a("中有詳細介紹，但如果你是初學者，官方説明就比必要的信息多得多。本文采用一種簡化的方法。",-1))]),s[41]||(s[41]=i("h3",{id:"添加-elasticsearch-倉庫",tabindex:"-1"},[a("添加 Elasticsearch 倉庫 "),i("a",{class:"header-anchor",href:"#添加-elasticsearch-倉庫","aria-label":"Permalink to “添加 Elasticsearch 倉庫”"},"​")],-1)),i("p",null,[s[7]||(s[7]=a("首先，將 Elasticsearch 倉庫添加到你的系統，以便你可以根據需要安裝它並接收更新。如何做取決於你的發行版。在基於 RPM 的系統上，例如 ",-1)),e(n,{href:"https://getfedora.org"},{default:t(()=>[...s[3]||(s[3]=[a("Fedora",-1)])]),_:1}),s[8]||(s[8]=a("、[CentOS] ",-1)),e(n,{href:"https://www.centos.org"},{default:t(()=>[...s[4]||(s[4]=[a("4",-1)])]),_:1}),s[9]||(s[9]=a("、",-1)),e(n,{href:"https://www.redhat.com/en/technologies/linux-platforms/enterprise-linux"},{default:t(()=>[...s[5]||(s[5]=[a("Red Hat Enterprise Linux（RHEL）",-1)])]),_:1}),s[10]||(s[10]=a(" 或 ",-1)),e(n,{href:"https://www.opensuse.org"},{default:t(()=>[...s[6]||(s[6]=[a("openSUSE",-1)])]),_:1}),s[11]||(s[11]=a("，（本文任何地方引用 Fedora 或 RHEL 的也適用於 CentOS 和 openSUSE）在 ",-1)),s[12]||(s[12]=i("code",null,"/etc/yum.repos.d/",-1)),s[13]||(s[13]=a(" 中創建一個名為 ",-1)),s[14]||(s[14]=i("code",null,"elasticsearch.repo",-1)),s[15]||(s[15]=a(" 的倉庫描述文件：",-1))]),s[42]||(s[42]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat &lt;&lt; EOF | sudo tee /etc/yum.repos.d/elasticsearch.repo</span></span>
<span class="line"><span>[elasticsearch-7.x]</span></span>
<span class="line"><span>name=Elasticsearch repository for 7.x packages</span></span>
<span class="line"><span>baseurl=https://artifacts.elastic.co/packages/oss-7.x/yum</span></span>
<span class="line"><span>gpgcheck=1</span></span>
<span class="line"><span>gpgkey=https://artifacts.elastic.co/GPG-KEY-elasticsearch</span></span>
<span class="line"><span>enabled=1</span></span>
<span class="line"><span>autorefresh=1</span></span>
<span class="line"><span>type=rpm-md</span></span>
<span class="line"><span>EOF</span></span></code></pre></div><p>在 Ubuntu 或 Debian 上，不要使用 <code>add-apt-repository</code> 工具。由於它自身默認的和 Elasticsearch 倉庫提供的不匹配而導致錯誤。相反，設置這個：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;deb https://artifacts.elastic.co/packages/oss-7.x/apt stable main&quot; | sudo tee -a /etc/apt/sources.list.d/elastic-7.x.list</span></span></code></pre></div><p>在你從該倉庫安裝之前，導入 GPG 公鑰，然後更新：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-key adv --keyserver \\</span></span>
<span class="line"><span>hkp://keyserver.ubuntu.com:80 \\</span></span>
<span class="line"><span>--recv D27D666CD88E42B4</span></span>
<span class="line"><span>$ sudo apt update</span></span></code></pre></div>`,5)),i("p",null,[s[17]||(s[17]=a("此存儲庫僅包含 Elasticsearch 的開源功能，在 ",-1)),e(n,{href:"http://www.apache.org/licenses/"},{default:t(()=>[...s[16]||(s[16]=[a("Apache 許可證",-1)])]),_:1}),s[18]||(s[18]=a("下發布，沒有提供訂閲版本的額外功能。如果你需要僅限訂閲的功能（這些功能是",-1)),s[19]||(s[19]=i("strong",null,"並不",-1)),s[20]||(s[20]=a("開源），那麼 ",-1)),s[21]||(s[21]=i("code",null,"baseurl",-1)),s[22]||(s[22]=a(" 必須設置為：",-1))]),s[43]||(s[43]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>baseurl=https://artifacts.elastic.co/packages/7.x/yum</span></span></code></pre></div><h3 id="安裝-elasticsearch" tabindex="-1">安裝 Elasticsearch <a class="header-anchor" href="#安裝-elasticsearch" aria-label="Permalink to “安裝 Elasticsearch”">​</a></h3><p>你需要安裝的軟件包的名稱取決於你使用的是開源版本還是訂閲版本。本文使用開源版本，包名最後有 <code>-oss</code> 後綴。如果包名後沒有 <code>-oss</code>，那麼表示你請求的是僅限訂閲版本。</p><p>如果你創建了訂閲版本的倉庫卻嘗試安裝開源版本，那麼就會收到“非指定”的錯誤。如果你創建了一個開源版本倉庫卻沒有將 <code>-oss</code> 添加到包名後，那麼你也會收到錯誤。</p><p>使用包管理器安裝 Elasticsearch。例如，在 Fedora、CentOS 或 RHEL 上運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install elasticsearch-oss</span></span></code></pre></div><p>在 Ubuntu 或 Debian 上，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install elasticsearch-oss</span></span></code></pre></div><p>如果你在安裝 Elasticsearch 時遇到錯誤，那麼你可能安裝的是錯誤的軟件包。如果你想如本文這樣使用開源包，那麼請確保使用正確的 apt 倉庫或在 Yum 配置正確的 <code>baseurl</code>。</p><h3 id="啓動並啓用-elasticsearch" tabindex="-1">啓動並啓用 Elasticsearch <a class="header-anchor" href="#啓動並啓用-elasticsearch" aria-label="Permalink to “啓動並啓用 Elasticsearch”">​</a></h3><p>安裝 Elasticsearch 後，你必須啓動並啓用它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo systemctl daemon-reload</span></span>
<span class="line"><span>$ sudo systemctl enable --now elasticsearch.service</span></span></code></pre></div><p>要確認 Elasticsearch 在其默認端口 9200 上運行，請在 Web 瀏覽器中打開 <code>localhost:9200</code>。你可以使用 GUI 瀏覽器，也可以在終端中執行此操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl localhost:9200</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  &quot;name&quot; : &quot;fedora30&quot;,</span></span>
<span class="line"><span>  &quot;cluster_name&quot; : &quot;elasticsearch&quot;,</span></span>
<span class="line"><span>  &quot;cluster_uuid&quot; : &quot;OqSbb16NQB2M0ysynnX1hA&quot;,</span></span>
<span class="line"><span>  &quot;version&quot; : {</span></span>
<span class="line"><span>    &quot;number&quot; : &quot;7.2.0&quot;,</span></span>
<span class="line"><span>    &quot;build_flavor&quot; : &quot;oss&quot;,</span></span>
<span class="line"><span>    &quot;build_type&quot; : &quot;rpm&quot;,</span></span>
<span class="line"><span>    &quot;build_hash&quot; : &quot;508c38a&quot;,</span></span>
<span class="line"><span>    &quot;build_date&quot; : &quot;2019-06-20T15:54:18.811730Z&quot;,</span></span>
<span class="line"><span>    &quot;build_snapshot&quot; : false,</span></span>
<span class="line"><span>    &quot;lucene_version&quot; : &quot;8.0.0&quot;,</span></span>
<span class="line"><span>    &quot;minimum_wire_compatibility_version&quot; : &quot;6.8.0&quot;,</span></span>
<span class="line"><span>    &quot;minimum_index_compatibility_version&quot; : &quot;6.0.0-beta1&quot;</span></span>
<span class="line"><span>  },</span></span>
<span class="line"><span>  &quot;tagline&quot; : &quot;You Know, for Search&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="安裝-kibana" tabindex="-1">安裝 Kibana <a class="header-anchor" href="#安裝-kibana" aria-label="Permalink to “安裝 Kibana”">​</a></h3><p>Kibana 是 Elasticsearch 數據可視化的圖形界面。它包含在 Elasticsearch 倉庫，因此你可以使用包管理器進行安裝。與 Elasticsearch 本身一樣，如果你使用的是 Elasticsearch 的開源版本，那麼必須將 <code>-oss</code> 放到包名最後，訂閲版本則不用（兩者安裝需要匹配）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install kibana-oss</span></span></code></pre></div><p>在 Ubuntu 或 Debian 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install kibana-oss</span></span></code></pre></div><p>Kibana 在端口 5601 上運行，因此打開圖形化 Web 瀏覽器並進入 <code>localhost:5601</code> 來開始使用 Kibana，如下所示：</p><p><img src="https://opensource.com/sites/default/files/uploads/kibana.jpg" alt="Kibana running in Firefox." title="Kibana running in Firefox."></p><h3 id="故障排除" tabindex="-1">故障排除 <a class="header-anchor" href="#故障排除" aria-label="Permalink to “故障排除”">​</a></h3><p>如果在安裝 Elasticsearch 時出現錯誤，請嘗試手動安裝 Java 環境。在 Fedora、CentOS 和 RHEL 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install java-openjdk-devel java-openjdk</span></span></code></pre></div><p>在 Ubuntu 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install default-jdk</span></span></code></pre></div><p>如果所有其他方法都失敗，請嘗試直接從 Elasticsearch 服務器安裝 Elasticsearch RPM：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget https://artifacts.elastic.co/downloads/elasticsearch/elasticsearch-oss-7.2.0-x86_64.rpm{,.sha512}</span></span>
<span class="line"><span>$ shasum -a 512 -c elasticsearch-oss-7.2.0-x86_64.rpm.sha512 &amp;&amp; sudo rpm --install elasticsearch-oss-7.2.0-x86_64.rpm</span></span></code></pre></div><p>在 Ubuntu 或 Debian 上，請使用 DEB 包。</p><p>如果你無法使用 Web 瀏覽器訪問 Elasticsearch 或 Kibana，那麼可能是你的防火牆阻止了這些端口。你可以通過調整防火牆設置來允許這些端口上的流量。例如，如果你運行的是 <code>firewalld</code>（Fedora 和 RHEL 上的默認防火牆，並且可以在 Debian 和 Ubuntu 上安裝），那麼你可以使用 <code>firewall-cmd</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo firewall-cmd --add-port=9200/tcp --permanent</span></span>
<span class="line"><span>$ sudo firewall-cmd --add-port=5601/tcp --permanent</span></span>
<span class="line"><span>$ sudo firewall-cmd --reload</span></span></code></pre></div><p>設置完成了，你可以關注我們接下來的 Elasticsearch 和 Kibana 安裝文章。</p><hr>`,33)),i("p",null,[s[24]||(s[24]=a("via: ",-1)),e(n,{href:"https://opensource.com/article/19/7/install-elasticsearch-and-kibana-linux"},{default:t(()=>[...s[23]||(s[23]=[a("https://opensource.com/article/19/7/install-elasticsearch-and-kibana-linux",-1)])]),_:1})]),i("p",null,[s[29]||(s[29]=a("作者：",-1)),e(n,{href:"https://opensource.com/users/seth"},{default:t(()=>[...s[25]||(s[25]=[a("Seth Kenlon",-1)])]),_:1}),s[30]||(s[30]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[26]||(s[26]=[a("lujun9972",-1)])]),_:1}),s[31]||(s[31]=a(" 譯者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:t(()=>[...s[27]||(s[27]=[a("geekpi",-1)])]),_:1}),s[32]||(s[32]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[28]||(s[28]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[35]||(s[35]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[33]||(s[33]=[a("LCTT",-1)])]),_:1}),s[36]||(s[36]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:t(()=>[...s[34]||(s[34]=[a("Linux中國",-1)])]),_:1}),s[37]||(s[37]=a(" 榮譽推出",-1))])])}const q=p(u,[["render",c]]);export{y as __pageData,q as default};
